                "src": src,
                "dst": dst,
                "vlan": vlan,
                "ethertype": ethertype,
                "priority": priority,
                "action": action,
                "to_vlan": to_vlan,
            }
        )
    return bridges, links, delay, bridge, ports, age, storm, lags, mirror, parsed


